import {createGame,placeError,finishPlacement,probe,toggleCorrection,resolve,publicView,edges,edgeId,endpoints,syndrome} from './toric-model.js';
import {createAttack,defenderPlan} from './toric-ai.js';
const $=id=>document.getElementById(id), allEdges=edges(5), coord=e=>`${e.orientation==='h'?'横':'竖'} ${e.x+1},${e.y+1}`;
let difficulty='standard';
let game,mode='defender',tool='Z',curtain=false,busy=false,replayLayer='residual',history=[],round=1,scores=[0,0],pools=[3,3],practiceError=null,tutorialStep=0,seed=0,generation=0;
const tutorialCopy=[
['01 / 创建、移动与融合','Z 在边的两个顶点翻转 e。错误在第 2 行第 2 条横边：点它会融合；点相邻边会移动端点，点远处边会创建一对。'],
['02 / m 走在对偶格上','珊瑚色 m 在面心。选择 X，点击第 3 行第 3 条竖边；这条边会同时翻转左右两面的 m。'],
['03 / 小绕路也能恢复','错误是一条 Z 横边。用下方正方形的另外三边纠错，端点一样会清空；残余是可收缩小环，仍然守胜。'],
['04 / 消失不等于胜利','Z 错误在第一行的前两条横边。点击第一行第 3、4、5 条横边：e 会消失，但残余绕环面一周，攻击者获胜。'],
['05 / 同边 Y，不是融合','第 3 行第 3 条横边同时有 X 和 Z：Y 产生 2 个 e 和 2 个 m。分别用 Z、X 纠错；e 与 m 不能相互湮灭。'],
['06 / 侦察是一份经典日志','选侦察，点第 2 行第 2 条横边，读取原始 Z 记录；随后用 Z 融合。探针消耗一次，读的是游戏的外部错误日志，不是真实量子态。']
];
const tutorialAttacks=[
[['h:1:1','Z']],[['v:2:2','X']],[['h:1:1','Z']],[['h:0:0','Z'],['h:1:0','Z']],[['h:2:2','Y']],[['h:1:1','Z']]
];
const tutorialCorrections=[
[['h:1:1','Z']],[['v:2:2','X']],[['v:1:1','Z'],['h:1:2','Z'],['v:2:1','Z']],[['h:2:0','Z'],['h:3:0','Z'],['h:4:0','Z']],[['h:2:2','Z'],['h:2:2','X']],[['h:1:1','Z']]
];
function activeDefender(){return mode==='series'?(round%2?1:0):1;}
function visiblePool(i){return pools[i]-(mode==='series'&&game?.phase==='play'&&i===activeDefender()?game.probes.length:0);}
function role(){return game?.phase==='placement'&&!curtain?'attacker':'defender';}
function view(){return publicView(game,role());}
function notice(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);}
function failure(e){const map={'Attack budget exceeded: each layer ≤4, total ≤6':'布错超出预算：X、Z 各最多 4 个边分量，合计最多 6 个分量。','Attack must have a nonzero syndrome':'提交时必须至少留下一对任意子，请调整错误链。','This edge was already probed':'这条边已经侦察过，请查看下方原始日志。','No probes remaining':'本局探针已用完；仍可任意修改纠错草稿。'};notice(map[e.message]||`这步未执行：${e.message}`,true);}
function fresh(m,keepSeries=false){generation++;difficulty=$('difficulty').value;mode=m;busy=false;curtain=false;history=[];tool='Z';replayLayer='residual';practiceError=null;seed=Math.floor(Math.random()*0xffffffff);if(!keepSeries){round=1;scores=[0,0];pools=[3,3];tutorialStep=0;}let budget=mode==='series'?Math.min(2,pools[activeDefender()]):mode==='tutorial'?0:1;game=createGame({size:5,probeBudget:budget});if(mode==='defender'){const attack=createAttack({seed,difficulty});for(const l of ['X','Z'])for(const edge of attack.error[l])game=placeError(game,edge,l);game=finishPlacement(game);}if(mode==='tutorial')loadTutorial();render();notice(mode==='defender'?'AI 已提交隐藏错误链。你只看见端点；先想想路径，再决定是否侦察。':mode==='tutorial'?tutorialCopy[tutorialStep][1]:'选择 Z 或 X，点击棋盘的边秘密布错。');$('setup').close();}
function loadTutorial(){game=createGame({probeBudget:tutorialStep===5?1:0});for(const [edge,l] of tutorialAttacks[tutorialStep])game=placeError(game,edge,l);practiceError=publicView(game,'attacker').error;game=finishPlacement(game);tool=tutorialStep===1?'X':tutorialStep===5?'probe':'Z';history=[];replayLayer='residual';}
function drawBoard(v){const n=5,start=52,gap=88,end=start+5*gap,px=x=>start+x*gap;let chain={X:[],Z:[]},classExtra='';if(v.phase==='placement'&&v.error)chain=v.error;else if(v.phase==='resolved'){chain=replayLayer==='error'?v.error:replayLayer==='correction'?v.correction:v.result.residual;classExtra=replayLayer==='error'?'error-chain':replayLayer==='residual'?'residual':'';}else chain=v.correction;const sets={X:new Set(chain.X.map(e=>edgeId(e))),Z:new Set(chain.Z.map(e=>edgeId(e)))};const probeMap=new Map(v.probes.map(p=>[edgeId(p.edge),p.result]));const legal=!busy&&!curtain&&v.phase!=='resolved';const currentTool=tool==='probe'?'Z':tool;let html=`<svg class="toric-board" viewBox="0 0 580 566" role="group" aria-label="5乘5环面棋盘，50条可操作边"><text x="290" y="18" fill="#a4b298" font-size="9" text-anchor="middle" letter-spacing="3">← 左右相接 · 上下相接 →</text>`;
for(let y=0;y<5;y++)for(let x=0;x<5;x++)html+=`<rect x="${px(x)}" y="${px(y)}" width="${gap}" height="${gap}" fill="${(x+y)%2?'#1d3025':'#23362a'}" opacity=".7"/>`;
for(let i=0;i<5;i++){html+=`<text x="${px(i)}" y="40" fill="#8b9d85" font-size="9" text-anchor="middle">${i+1}</text><text x="29" y="${px(i)+3}" fill="#8b9d85" font-size="9" text-anchor="middle">${i+1}</text>`;}
if(mode==='practice'&&practiceError&&v.phase==='play'){for(const layer of ['X','Z'])for(const e of practiceError[layer]){const ax=px(e.x),ay=px(e.y),bx=ax+(e.orientation==='h'?gap:0),by=ay+(e.orientation==='v'?gap:0);html+=`<path d="M${ax} ${ay}L${bx} ${by}" stroke="var(--gold)" stroke-width="11" stroke-dasharray="3 6" opacity=".65" pointer-events="none" role="img" aria-label="原始错误 ${layer}，${coord(e)}"/>`;}}
for(const e of allEdges){const id=edgeId(e),x1=px(e.x),y1=px(e.y),x2=x1+(e.orientation==='h'?gap:0),y2=y1+(e.orientation==='v'?gap:0),hasX=sets.X.has(id),hasZ=sets.Z.has(id),active=hasX||hasZ;const cls=[legal?'':'locked',hasX?'active-x':'',hasZ?'active-z':'',active?classExtra:''].join(' ');const description=`${coord(e)}${(e.orientation==='h'&&e.x===4)||(e.orientation==='v'&&e.y===4)?'，跨周期边界':''}${hasZ?'，已选 Z':''}${hasX?'，已选 X':''}${probeMap.has(id)?`，原始日志 ${probeMap.get(id)}`:''}`;html+=`<g class="edge-hit ${cls}" data-edge="${id}" role="button" tabindex="${legal?'0':'-1'}" aria-label="${description}" aria-disabled="${!legal}" ${legal?`aria-pressed="${currentTool==='Z'?hasZ:hasX}"`:''}><title>${description}</title><path class="hit-line" d="M${x1} ${y1}L${x2} ${y2}"/><path class="edge-line" d="M${x1+((e.orientation==='h')?8:0)} ${y1+((e.orientation==='v')?8:0)}L${x2-((e.orientation==='h')?8:0)} ${y2-((e.orientation==='v')?8:0)}"/>${hasX&&hasZ?`<path d="M${x1+(e.orientation==='v'?5:8)} ${y1+(e.orientation==='h'?5:8)}L${x2+(e.orientation==='v'?5:-8)} ${y2+(e.orientation==='h'?5:-8)}" stroke="var(--coral)" stroke-width="3" fill="none" pointer-events="none"/>`:''}${active&&!probeMap.has(id)?`<text x="${(x1+x2)/2+(e.orientation==='v'?12:0)}" y="${(y1+y2)/2+(e.orientation==='h'?-9:3)}" font-size="10" text-anchor="middle" fill="${classExtra?'var(--gold)':hasZ?'var(--cyan)':'var(--coral)'}">${hasX&&hasZ?'Y':hasX?'X':'Z'}</text>`:''}${probeMap.has(id)?`<circle class="probe-dot" cx="${(x1+x2)/2}" cy="${(y1+y2)/2}" r="9"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2+3}" font-size="9" text-anchor="middle" fill="#142118">${probeMap.get(id)}</text>`:''}</g>`;}
const sy=v.phase==='resolved'?{e:syndrome(chain.Z,'Z'),m:syndrome(chain.X,'X')}:v.syndrome,es=new Set(sy.e.map(p=>`${p.x},${p.y}`)),ms=new Set(sy.m.map(p=>`${p.x},${p.y}`));for(let y=0;y<=5;y++)for(let x=0;x<=5;x++){if(x===5&&y===5)continue;const ghost=x===5||y===5,e=es.has(`${x%5},${y%5}`);html+=`<g opacity="${ghost?'.42':'1'}" pointer-events="none" role="img" aria-label="${e?`e 任意子，顶点 ${x%5+1},${y%5+1}${ghost?'，周期副本':''}`:`空顶点 ${x%5+1},${y%5+1}`}" ${e?'':'aria-hidden="true"'}><circle class="${e?'anyon-e':'board-node'}" cx="${px(x)}" cy="${px(y)}" r="${e?15:4}"/>${e?`<text class="anyon-letter" x="${px(x)}" y="${px(y)-1}" fill="var(--cyan)">e</text>`:''}</g>`;}
for(let y=0;y<5;y++)for(let x=0;x<5;x++){const cx=px(x)+gap/2,cy=px(y)+gap/2;if(ms.has(`${x},${y}`))html+=`<g pointer-events="none" role="img" aria-label="m 任意子，面 ${x+1},${y+1}"><path class="anyon-m" d="M${cx} ${cy-17}l17 17-17 17-17-17Z"/><text class="anyon-letter" x="${cx}" y="${cy-1}" fill="var(--coral)">m</text></g>`;else html+=`<circle cx="${cx}" cy="${cy}" r="1.5" fill="#687c5d" opacity=".5" pointer-events="none"/>`;}
html+=`<text x="${end+19}" y="${start+190}" fill="#93a28a" font-size="9" transform="rotate(90 ${end+19} ${start+190})" text-anchor="middle">重复的第 1 列 ↗</text><text x="270" y="${end+25}" fill="#93a28a" font-size="9" text-anchor="middle">↓ 重复的第 1 行 · 不是新的棋子</text></svg>`;$('game-board').innerHTML=html;
$('game-board').querySelectorAll('[data-edge]').forEach(el=>{el.onclick=()=>legal&&clickEdge(el.dataset.edge);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(legal)clickEdge(el.dataset.edge);}};});}
function clickEdge(id){try{const before=view(),oldCount=before.syndrome.e.length+before.syndrome.m.length;if(game.phase==='placement'){history.push(game);game=placeError(game,id,tool);}else if(tool==='probe'){game=probe(game,id);history=[];const p=publicView(game).probes.at(-1);render(id);notice(`${coord(p.edge)} 的原始错误日志：${p.result}。此记录不随纠错改变。`);return;}else{history.push(game);game=toggleCorrection(game,id,tool);}render(id);const v=view(),count=v.syndrome.e.length+v.syndrome.m.length;notice(count<oldCount?`融合发生：${oldCount-count} 个同种任意子消失。${count===0?'端点已清空，但全局记忆尚未验证。':''}`:count>oldCount?'这一步创建了一对任意子。再次点击可抵消；也可以延长路径移动它们。':(mode==='practice'||mode==='tutorial'?'任意子沿你选中的边移动了。试着让同种端点相遇。':'任意子沿你选中的边移动了。原始错误链仍然隐藏。'));}catch(e){if(history.at(-1)===game)history.pop();failure(e);}}
function render(focusEdge){const v=view(),placement=v.phase==='placement',resolved=v.phase==='resolved',count=v.syndrome.e.length+v.syndrome.m.length;document.querySelectorAll('.phase-track li').forEach(el=>{el.classList.toggle('current',el.dataset.phase===(curtain?'handoff':v.phase));el.classList.toggle('done',resolved&&el.dataset.phase!=='resolved');});$('board-status').textContent=resolved?'REPLAY / 全部公开':curtain?'PRIVACY SCREEN':placement?'PRIVATE / 仅攻击者可见':mode==='practice'?'PRACTICE / 原链明牌':'PUBLIC / 只显示端点与草稿';$('board-title').textContent=`5 × 5 环面 / ${mode==='series'?`系列赛第 ${round} / 6 局`:'周期边界'}`;
$('score').innerHTML=mode==='series'?`<span>A <b>${scores[0]}</b> · 探针 ${visiblePool(0)}</span><span>B <b>${scores[1]}</b> · 探针 ${visiblePool(1)}</span>`:`<span>${({defender:'单人 · 你是守方',attacker:'单人 · 你是攻击者',local:'本地双人 · 非联网',practice:'明牌自由练习',tutorial:'教学模式'})[mode]}</span>`;
$('role-label').textContent=curtain?'HANDOFF / 交接中':placement?`ATTACKER / ${mode==='series'?`玩家 ${round%2?'A':'B'} · `:''}攻击者`:resolved?'ROUND REVEALED / 棋局已揭晓':`DEFENDER / ${mode==='series'?`玩家 ${activeDefender()?'B':'A'} · `:''}${busy?'AI 正在决策':'守方'}`;
$('phase-heading').textContent=curtain?'请交给守方':placement?'布下一条看不见的路':resolved?(v.result.winner==='defender'?'守住了全局记忆':'攻击穿过了防线'):'把端点连起来';
$('instruction').textContent=curtain?'秘密错误链已锁定。请移开视线，等待另一位玩家接手。':placement?'Z 在顶点间留下 e；X 在相邻面间留下 m。重复点击同种操作可撤回。':resolved?({syndrome:'仍有任意子未融合，纠错没有完成。攻击者获胜。',logical:'任意子全部消失，但残余链绕过环面，逻辑记忆被改变。攻击者获胜。',corrected:'任意子已清空，残余绕行位全为 0。守方获胜。'})[v.result.reason]:busy?'AI 只根据公开端点、错误上限与经典日志决策，不读取隐藏错误链。':'先用 Z 或 X 移动同种任意子。探针能查看一条边的原始错误，但数量有限。';
$('resources').innerHTML=placement&&!curtain?`<div class="resource"><span>秘密错误用量</span><strong>${v.cost.total}</strong><small> / 6</small></div><div class="resource"><span>每种最多 4 个分量</span><strong class="e-color">${v.cost.Z}</strong><small> Z · </small><strong class="m-color">${v.cost.X}</strong><small> X</small></div>`:`<div class="resource"><span>${resolved?'最终残余端点':'剩余端点'}</span><strong class="e-color">${v.syndrome.e.length}</strong><small> e · </small><strong class="m-color">${v.syndrome.m.length}</strong><small> m</small></div><div class="resource"><span>本局可用探针</span><strong>${v.probesRemaining}</strong><small> / ${v.config.probeBudget}</small></div>`;
$('tools').hidden=resolved||curtain;$('tools').innerHTML=`<button data-tool="Z" class="${tool==='Z'?'selected':''}" aria-pressed="${tool==='Z'}">Z · 移动 e</button><button data-tool="X" class="${tool==='X'?'selected':''}" aria-pressed="${tool==='X'}">X · 移动 m</button>${!placement?`<button data-tool="probe" class="${tool==='probe'?'selected':''}" aria-pressed="${tool==='probe'}" ${v.probesRemaining===0?'disabled':''}>⌕ 侦察</button>`:''}`;$('tools').querySelectorAll('button').forEach(b=>{b.disabled ||= busy;b.onclick=()=>{tool=b.dataset.tool;render();notice(tool==='probe'?'点击一条物理边，读取原始 I / X / Z / Y 日志；将消耗 1 枚探针。':tool==='Z'?'Z 工具：横边连接左右顶点，竖边连接上下顶点。':'X 工具：横边影响上下两面，竖边影响左右两面。');};});
$('new-game').disabled=busy;$('main-action').disabled=busy||curtain||(!placement&&!resolved&&count>0);$('main-action').textContent=placement?'锁定错误链 →':resolved?mode==='series'?(round<6?'交换攻守 · 下一局 →':'查看系列赛结果 →'):mode==='tutorial'?(tutorialStep<tutorialCopy.length-1?'继续下一课 →':'教学结束 · 来一局 →'):'再来一局 →':count===0?'锁定恢复 · 揭晓 →':`还需融合 ${count} 个任意子`;$('undo').disabled=history.length===0||resolved||busy||curtain;$('clear').disabled=resolved||busy||curtain;$('undo').parentElement.hidden=resolved||curtain;
$('replay-controls').hidden=!resolved;$('replay-controls').innerHTML=resolved?['error','correction','residual'].map((key,i)=>`<button data-replay="${key}" class="${replayLayer===key?'selected':''}">${['原始错误','纠错草稿','残余链'][i]}</button>`).join(''):'';$('replay-controls').querySelectorAll('button').forEach(b=>b.onclick=()=>{replayLayer=b.dataset.replay;render();});$('result-bits').hidden=!resolved;$('result-bits').innerHTML=resolved?(v.result.winding?v.result.winding.map((b,i)=>`<span class="${b?'on':''}"><small>${['Z↔','Z↕','X↔','X↕'][i]}</small>${b}</span>`).join(''):'<p class="empty-log">残余未闭合，不定义同调绕行位。</p>'):'';
$('probe-log').innerHTML=v.probes.length?`<ul class="probe-list">${v.probes.map(p=>`<li>${coord(p.edge)} <strong>→ ${p.result}</strong></li>`).join('')}</ul>`:'<p class="empty-log">尚无侦察记录。探针读取原始错误日志，不是量子测量。</p>';
$('board-caption').textContent=resolved?({error:'金色虚线：攻击者最初提交的错误链。',correction:'青色 Z / 珊瑚 X：守方最终提交的纠错链。',residual:'紫色：错误 ⊕ 纠错。闭合后四个绕行奇偶位任一非零，才是逻辑错误。'})[replayLayer]:tool==='probe'?'侦察已选中：点边读取原始错误日志，消耗 1 枚探针。':tool==='Z'?'Z 操作影响边两端的顶点 e。左右、上下边界相接。':'X 操作影响边两侧的面心 m。左右、上下边界相接。';
$('tutorial').hidden=mode!=='tutorial'&&mode!=='practice';$('tutorial').innerHTML=mode==='tutorial'?`<p><b>${tutorialCopy[tutorialStep][0]}</b><br>${tutorialCopy[tutorialStep][1]}</p><button id="demo-step" class="button secondary small">${resolved?'重练本课':'示范这一步'}</button>`:mode==='practice'?'<p><b>自由练习 · 明牌</b><br>自己布错，再自己纠错。金色虚线保留原错误位置；结束后分别查看三条链。</p>':'';$('demo-step')?.addEventListener('click',()=>{if(resolved){loadTutorial();render();return;}const target=tutorialCorrections[tutorialStep];clearDraft();if(tutorialStep===5&&view().probesRemaining)game=probe(game,'h:1:1');for(const [id,l] of target)game=toggleCorrection(game,id,l);render();notice('端点清空了。点击「锁定恢复 · 揭晓」，检查全局记忆。');});
$('shield').hidden=!curtain;$('shield').innerHTML=curtain?`<div><div class="shield-mark">◈</div><div class="eyebrow">PASS THE SCREEN</div><h2>${mode==='series'?`请交给玩家 ${activeDefender()?'B':'A'}`:'请交给守方'}</h2><p>攻击者请移开视线。隐藏链已从棋盘与界面移除，准备好后由守方解锁。<br>同屏轮换 · 非联网游戏</p><button id="take-seat" class="button primary">我是守方 · 开始侦察 →</button></div>`:'';$('take-seat')?.addEventListener('click',()=>{curtain=false;tool='Z';render();notice('你只看得见端点与公开日志。选择合适的配对路径，保住全局记忆。');});drawBoard(v);if(focusEdge)$('game-board').querySelector(`[data-edge="${focusEdge}"]`)?.focus({preventScroll:true});}
function clearDraft(){const v=view();if(game.phase==='placement'){history.push(game);for(const l of ['X','Z'])for(const edge of v.error[l])game=placeError(game,edge,l);}else{history.push(game);for(const l of ['X','Z'])for(const edge of v.correction[l])game=toggleCorrection(game,edge,l);}}
function settle(){game=resolve(game);history=[];if(mode==='series'){pools[activeDefender()]-=game.probes.length;const winner=game.result.winner==='defender'?activeDefender():1-activeDefender();scores[winner]++;}render();notice(game.result.reason==='logical'?'端点局域上全部正常，但紫色残余链绕过周期边界。这就是一次逻辑错误。':game.result.reason==='corrected'?'纠错完成。可以切换原始错误、纠错草稿与残余链，复盘路径差异。':'纠错未完成：棋盘上仍有任意子。切换复盘图层检查漏掉的路径。');}
async function aiTurn(){const token=generation;busy=true;render();notice('AI 正在根据公开信息规划；它看不到你的错误链。');await new Promise(r=>setTimeout(r,80));if(token!==generation)return;try{let node=defenderPlan(publicView(game,'defender'),{seed:Math.floor(Math.random()*0xffffffff),difficulty});while(node.probe&&publicView(game).probesRemaining>0){game=probe(game,node.probe);const answer=publicView(game).probes.at(-1).result;node=node.branches[answer];if(!node)throw new Error('AI strategy branch unavailable');}for(const l of ['X','Z'])for(const edge of node.correction[l])game=toggleCorrection(game,edge,l);busy=false;settle();}catch(e){busy=false;render();failure(e);}}
$('main-action').onclick=()=>{try{if(game.phase==='placement'){if(mode==='practice')practiceError=view().error;game=finishPlacement(game);history=[];if(mode==='attacker'){aiTurn();return;}curtain=mode==='local'||mode==='series';tool='Z';render();notice(curtain?'秘密错误链已锁定，等待守方接手。':'错误已锁定。现在选择纠错边，把任意子配对融合。');}else if(game.phase==='play'){const v=view();if(v.syndrome.e.length+v.syndrome.m.length>0&&!confirm('还有任意子没有融合。现在提交，攻击者会直接获胜。确定结束纠错吗？'))return;settle();}else if(mode==='series'){if(round<6){round++;fresh(mode,true);}else{const result=scores[0]===scores[1]?'平局':`玩家 ${scores[0]>scores[1]?'A':'B'} 获胜`;notice(`六局结束：A ${scores[0]} : ${scores[1]} B。${result}。点击「换桌 / 新对局」开始新系列。`);$('main-action').disabled=true;}}else if(mode==='tutorial'){if(tutorialStep<tutorialCopy.length-1){tutorialStep++;loadTutorial();render();notice(tutorialCopy[tutorialStep][1]);}else fresh('defender');}else fresh(mode);}catch(e){failure(e);}};
$('undo').onclick=()=>{if(history.length){game=history.pop();render();notice('已撤销最近一步草稿。侦察记录与已消耗探针不会撤回。');}};$('clear').onclick=()=>{try{clearDraft();render();notice('草稿已清空。侦察记录保留。');}catch(e){failure(e);}};$('new-game').onclick=()=>$('setup').showModal();$('close-setup').onclick=()=>$('setup').close();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>fresh(b.dataset.mode));
try{fresh('defender');}catch(e){$('phase-heading').textContent='棋局未能初始化';notice(e.message,true);}
